        'ROUND_ROBIN',
        'SWISS',
        'DRAW_MATIC',
        'LUCKY_DRAW',
        'FEED_IN',
        'FIRST_MATCH_LOSER_CONSOLATION',
        'ROUND_ROBIN_WITH_PLAYOFF',
        'DOUBLE_ELIMINATION',
