import { getPayloads, addNotice } from '../../global/state/globalState.mjs';
import { MODIFY_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function modifyParticipantsNotice({ tournamentId, participants }) {
    if (!participants?.length)
        return { ...SUCCESS };
    const byId = new Map();
    const buffered = getPayloads({ topic: MODIFY_PARTICIPANTS }).find((payload) => payload?.tournamentId === tournamentId);
    for (const participant of buffered?.participants ?? []) {
        if (participant?.participantId)
            byId.set(participant.participantId, participant);
    }
    for (const participant of participants) {
        if (participant?.participantId)
            byId.set(participant.participantId, participant);
    }
    addNotice({
        topic: MODIFY_PARTICIPANTS,
        key: tournamentId,
        payload: { tournamentId, participants: [...byId.values()] },
    });
    return { ...SUCCESS };
}

export { modifyParticipantsNotice };
