import { modifyParticipantsNotice } from '../notifications/participantNotifications.mjs';
import { updateTeamEventEntries } from './updateTeamEventEntries.mjs';
import { decorateResult } from '../../functions/global/decorateResult.mjs';
import { getTopics } from '../../global/state/globalState.mjs';
import { makeDeepCopy } from '../../tools/makeDeepCopy.mjs';
import { removeParticipantIdsFromAllTeams } from './removeIndividualParticipantIds.mjs';
import { TEAM, GROUP, INDIVIDUAL } from '../../constants/participantConstants.mjs';
import { MODIFY_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { MISSING_TOURNAMENT_RECORD, MISSING_VALUE, PARTICIPANT_NOT_FOUND, INVALID_PARTICIPANT_TYPE, INVALID_PARTICIPANT_IDS } from '../../constants/errorConditionConstants.mjs';

function addIndividualParticipantIds({ individualParticipantIds, groupingParticipantId, removeFromOtherTeams, tournamentRecord, }) {
    const stack = 'addIndividualParticipantIds';
    if (!tournamentRecord)
        return decorateResult({
            result: { error: MISSING_TOURNAMENT_RECORD },
            stack,
        });
    if (!groupingParticipantId || !individualParticipantIds)
        return decorateResult({ result: { error: MISSING_VALUE }, stack });
    const tournamentParticipants = tournamentRecord.participants ?? [];
    const groupingParticipant = tournamentParticipants.find((participant) => participant.participantId === groupingParticipantId);
    if (!groupingParticipant)
        return decorateResult({ result: { error: PARTICIPANT_NOT_FOUND }, stack });
    if (groupingParticipant?.participantType && ![TEAM, GROUP].includes(groupingParticipant.participantType)) {
        return decorateResult({
            context: { participantType: groupingParticipant.participantType },
            result: { error: INVALID_PARTICIPANT_TYPE },
            stack,
        });
    }
    const invalidParticipantIds = individualParticipantIds.filter((participantId) => {
        const participant = tournamentParticipants.find((tournamentParticipant) => tournamentParticipant.participantId === participantId);
        return participant?.participantType !== INDIVIDUAL;
    });
    if (invalidParticipantIds.length)
        return decorateResult({
            result: { error: INVALID_PARTICIPANT_IDS, invalidParticipantIds },
            stack,
        });
    groupingParticipant.individualParticipantIds ??= [];
    const existingIndividualParticipantIds = groupingParticipant.individualParticipantIds;
    const participantIdsToAdd = individualParticipantIds.filter((participantId) => {
        const participantIsMember = existingIndividualParticipantIds.includes(participantId);
        return !participantIsMember;
    });
    if (participantIdsToAdd.length) {
        if (removeFromOtherTeams) {
            removeParticipantIdsFromAllTeams({
                individualParticipantIds: participantIdsToAdd,
                tournamentRecord,
            });
        }
        groupingParticipant.individualParticipantIds = groupingParticipant.individualParticipantIds.concat(...participantIdsToAdd);
    }
    const { topics } = getTopics();
    if (topics.includes(MODIFY_PARTICIPANTS)) {
        const updatedParticipant = tournamentParticipants.find(({ participantId }) => participantId === groupingParticipantId);
        modifyParticipantsNotice({ tournamentId: tournamentRecord.tournamentId, participants: [updatedParticipant] });
    }
    updateTeamEventEntries({
        individualParticipantIds,
        groupingParticipantId,
        tournamentRecord,
    });
    return {
        groupingParticipant: makeDeepCopy(groupingParticipant, false, true),
        added: participantIdsToAdd.length,
        ...SUCCESS,
    };
}

export { addIndividualParticipantIds };
