import { MISSING_OFFICIAL_RECORD, SUSPENSION_NOT_FOUND } from '../../constants/officiatingConstants.mjs';
import { INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { nowIso } from '../../tools/clock.mjs';

function removeSuspension({ officialRecord, suspensionId }) {
    if (!officialRecord)
        return { error: MISSING_OFFICIAL_RECORD };
    if (!suspensionId)
        return { error: INVALID_VALUES, context: { message: 'Missing suspensionId' } };
    const index = officialRecord.suspensions.findIndex((s) => s.suspensionId === suspensionId);
    if (index === -1)
        return { error: SUSPENSION_NOT_FOUND, context: { suspensionId } };
    officialRecord.suspensions.splice(index, 1);
    officialRecord.updatedAt = nowIso();
    return { ...SUCCESS };
}

export { removeSuspension };
