import { buildIndividualIdsMap } from '../../participants/individualParticipantIds.mjs';
import { getEventAlternateParticipantIds } from './getEventAlternateParticipantids.mjs';
import { checkScoreHasValue } from '../../matchUp/checkScoreHasValue.mjs';
import { getFlightProfile } from '../../event/getFlightProfile.mjs';
import { getParticipantId } from '../../../functions/global/extractors.mjs';
import { matchUpsOf } from '../../../acquire/structureMembers.mjs';
import { makeDeepCopy } from '../../../tools/makeDeepCopy.mjs';
import { unique } from '../../../tools/arrays.mjs';
import { DIRECT_ENTRY_STATUSES } from '../../../constants/entryStatusConstants.mjs';
import { ASSIGN_SIDE_METHOD, REMOVE_PARTICIPANT, REMOVE_SIDE_METHOD } from '../../../constants/matchUpActionConstants.mjs';
import { SWAP_PARTICIPANTS, SWAP_ADHOC_PARTICIPANT_METHOD, ASSIGN_PARTICIPANT } from '../../../constants/positionActionConstants.mjs';
