import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getParticipants } from './getParticipants.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { TEAM, PAIR, GROUP } from '../../constants/participantConstants.mjs';

function getParticipantMembership({ tournamentRecord, participantId, }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    const { participants } = getParticipants({
        participantFilters: { participantTypes: [TEAM, PAIR, GROUP] },
        tournamentRecord,
    });
    const memberOf = (participants ?? []).filter((participant) => {
        return participant.individualParticipantIds?.includes(participantId);
    });
    return memberOf.reduce((groupingTypesMap, participant) => {
        const participantType = participant.participantType;
        if (participantType) {
            if (!groupingTypesMap[participantType])
                groupingTypesMap[participantType] = [];
            groupingTypesMap[participantType].push(participant);
        }
        return groupingTypesMap;
    }, {});
}

export { getParticipantMembership };
